package com.jobcom.web;
import com.jobcom.dao.ResumeDAO;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.nio.file.*;import java.util.*;
public class ResumeTemplateFileServlet extends HttpServlet{
 private final ResumeDAO dao=new ResumeDAO();
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("seekerId")==null){p.sendError(403);return;}try{long id=Long.parseLong(q.getParameter("id"));String relative=dao.templateFile(id);if(relative==null||!relative.matches("resume-templates/[a-fA-F0-9-]{36}\\.pdf")){p.sendError(404);return;}String configured=System.getenv("JOBCOM_UPLOAD_DIR"),real=getServletContext().getRealPath("/uploads");Path root=Paths.get(configured==null||configured.isBlank()?(real==null?Paths.get(System.getProperty("user.home"),"Job.com","uploads").toString():real):configured).toAbsolutePath().normalize();Path file=root.resolve(relative).normalize();if(!file.startsWith(root)||!Files.isRegularFile(file)){p.sendError(404);return;}p.setContentType("application/pdf");p.setHeader("Content-Disposition","inline; filename=\"ATS-resume-sample.pdf\"");p.setContentLengthLong(Files.size(file));try(InputStream in=Files.newInputStream(file);OutputStream out=p.getOutputStream()){in.transferTo(out);}}catch(NumberFormatException e){p.sendError(404);}catch(Exception e){getServletContext().log("Template sample could not be served",e);p.sendError(500);}}
}
